    "Call injected ✓": { en: "Call injected ✓", fr: "Appel injecté ✓", ar: "تم إدخال المكالمة ✓", es: "Llamada inyectada ✓", ru: "Введенный вызов ✓", zh: "调用注入 ✓" },
