    "Directory badge color": { en: "Directory badge color", fr: "Couleur du badge de l'annuaire", ar: "لون شارة الدليل", es: "Color de la insignia del directorio", ru: "Цвет значка каталога", zh: "目录徽章颜色" },
    "Directory badge label": { en: "Directory badge label", fr: "Étiquette de badge d'annuaire", ar: "تسمية شارة الدليل", es: "Etiqueta de insignia de directorio", ru: "Метка значка каталога", zh: "目录徽章标签" },
