    "Friend removed": { en: "Friend removed", fr: "Ami supprimé", ar: "تمت إزالة الصديق", es: "Amigo eliminado", ru: "Друг удалён", zh: "已删除好友" },
    "Friend removed.": { en: "Friend removed.", fr: "Ami supprimé.", ar: "تمت إزالة الصديق.", es: "Amigo eliminado.", ru: "Друг удален.", zh: "好友已删除。" },
    "Friend request cancelled.": { en: "Friend request cancelled.", fr: "Demande d'ami annulée.", ar: "تم إلغاء طلب الصداقة.", es: "Solicitud de amistad cancelada.", ru: "Запрос на добавление в друзья отменен.", zh: "好友请求已取消。" },
    "Friend request declined.": { en: "Friend request declined.", fr: "Demande d'ami refusée.", ar: "تم رفض طلب الصداقة.", es: "Solicitud de amistad rechazada.", ru: "Запрос на добавление в друзья отклонен.", zh: "好友请求被拒绝。" },
    "Friend request sent!": { en: "Friend request sent!", fr: "Demande d'ami envoyée !", ar: "تم إرسال طلب الصداقة!", es: "¡Solicitud de amistad enviada!", ru: "Запрос в друзья отправлен!", zh: "好友请求已发送！" },
