    "GIF conversion in progress...": { en: "GIF conversion in progress...", fr: "GIF conversion in progress...", ar: "GIF conversion in progress...", es: "Conversión GIF en curso...", ru: "Конвертация GIF...", zh: "GIF转换中..." },
    "GIF preview": { en: "GIF preview", fr: "Aperçu GIF", ar: "معاينة GIF", es: "Vista previa de GIF", ru: "Предварительный просмотр GIF", zh: "GIF 预览" },
    "GIF sent!": { en: "GIF sent!", fr: "GIF envoyé !", ar: "تم إرسال GIF!", es: "¡GIF enviado!", ru: "Гифка отправлена!", zh: "GIF 已发送！" },
