    "German": { en: "German", fr: "Allemand", ar: "الألمانية", es: "Alemán", ru: "немецкий", zh: "德语" },
    "German (Deutsch)": { en: "German (Deutsch)", fr: "allemand (allemand)", ar: "الألمانية (الألمانية)", es: "alemán (alemán)", ru: "немецкий (Deutsch)", zh: "德语（德语）" },
    "Get a random cat picture": { en: "Get a random cat picture", fr: "Obtenez une photo de chat au hasard", ar: "احصل على صورة قطة عشوائية", es: "Obtener una imagen de gato aleatoria", ru: "Получить случайное изображение кота", zh: "随机获取一张猫的图片" },
    "Get toasts for when chosen users send a message": { en: "Get toasts for when chosen users send a message", fr: "Obtenez des toasts lorsque des utilisateurs sélectionnés envoient un message", ar: "احصل على الخبز المحمص عندما يرسل المستخدمون المختارون رسالة", es: "Recibe brindis cuando los usuarios elegidos envían un mensaje", ru: "Получайте всплывающие уведомления о том, когда выбранные пользователи отправляют сообщение.", zh: "当选定的用户发送消息时获得祝酒词" },
