    "Install Spicetify?": { en: "Install Spicetify?", fr: "Installer Spicetify ?", ar: "تثبيت Spicetify؟", es: "¿Instalar Spicetify?", ru: "Установить Spicetify?", zh: "安装 Spicetify 吗？" },
    "Install extension command packs.": { en: "Install extension command packs.", fr: "Installez les packs de commandes d’extension.", ar: "تثبيت حزم أوامر الامتداد.", es: "Instale paquetes de comandos de extensión.", ru: "Установите пакеты команд расширения.", zh: "安装扩展命令包。" },
    "Installed Themes": { en: "Installed Themes", fr: "Thèmes installés", ar: "المواضيع المثبتة", es: "Temas instalados", ru: "Установленные темы", zh: "已安装的主题" },
