    "Last message pin:": { en: "Last message pin:", fr: "Épingle du dernier message :", ar: "دبوس الرسالة الأخيرة:", es: "Pin del último mensaje:", ru: "Пин последнего сообщения:", zh: "最后一条消息图钉：" },
    "Last.fm username": { en: "Last.fm username", fr: "Nom d'utilisateur Last.fm", ar: "اسم المستخدم Last.fm", es: "Nombre de usuario de Last.fm", ru: "Имя пользователя Last.fm", zh: "Last.fm 用户名" },
