    "Of measured heap increase": { en: "Of measured heap increase", fr: "De l'augmentation mesurée du tas", ar: "من زيادة الكومة المقاسة", es: "Del aumento medido del montón", ru: "Измеренного увеличения кучи", zh: "测量到的堆增加" },
    "Of measured plugin CPU": { en: "Of measured plugin CPU", fr: "Du CPU du plugin mesuré", ar: "من وحدة المعالجة المركزية البرنامج المساعد المقاسة", es: "De CPU del complemento medido", ru: "Измеренного процессора плагина", zh: "测得的插件CPU" },
