    "Old username displayed in tooltip": { en: "Old username displayed in tooltip", fr: "Old username displayed in tooltip", ar: "Old username displayed in tooltip", es: "Antiguo seudónimo mostrado en le tooltip", ru: "Старое имя пользователя в подсказке", zh: "旧用户名显示在工具提示中" },
    "On startup": { en: "On startup", fr: "Au démarrage", ar: "عند بدء التشغيل", es: "Al iniciar", ru: "При запуске", zh: "启动时" },
