    "Open StereoInstaller": { en: "Open StereoInstaller", fr: "Ouvrez StereoInstaller", ar: "افتح برنامج تثبيت الاستريو", es: "Abrir StereoInstaller", ru: "Открыть стереоустановщик", zh: "打开立体声安装程序" },
    "Open Surveillance": { en: "Open Surveillance", fr: "Surveillance ouverte", ar: "المراقبة المفتوحة", es: "Vigilancia abierta", ru: "Открытое наблюдение", zh: "开放式监控" },
