    "Record Voice Message": { en: "Record Voice Message", fr: "Enregistrer un message vocal", ar: "سجل الرسالة الصوتية", es: "Grabar mensaje de voz", ru: "Запись голосового сообщения", zh: "录制语音留言" },
    "Recording...": { en: "Recording...", fr: "Recording...", ar: "Recording...", es: "Grabando...", ru: "Запись...", zh: "录音中..." },
    "Records mic + PC audio via ffmpeg.": { en: "Record mic + PC audio via ffmpeg.", fr: "Records mic + PC audio via ffmpeg.", ar: "Records mic + PC audio via ffmpeg.", es: "Graba micro + audio PC vía ffmpeg.", ru: "Запись микрофона + аудио ПК через ffmpeg.", zh: "通过 ffmpeg 录制麦克风和 PC 音频" },
    "Records screen + audio via ffmpeg.": { en: "Record screen + audio via ffmpeg.", fr: "Records screen + audio via ffmpeg.", ar: "Records screen + audio via ffmpeg.", es: "Graba pantalla + audio vía ffmpeg.", ru: "Запись экрана + аудио через ffmpeg.", zh: "通过 ffmpeg 录制屏幕+音频" },
    "Records screen + audio via ffmpeg. Supports MP4, WebM, GIF with GPU encoding.": { en: "Records screen + audio via ffmpeg. Supports MP4, WebM, GIF with GPU encoding.", fr: "Records screen + audio via ffmpeg. Supports MP4, WebM, GIF with GPU encoding.", ar: "Records screen + audio via ffmpeg. Supports MP4, WebM, GIF with GPU encoding.", es: "Graba pantalla + audio via ffmpeg. Soporta MP4, WebM, GIF con codificación GPU.", ru: "Запись экрана + аудио через ffmpeg. Поддерживает MP4, WebM, GIF с GPU кодированием.", zh: "通过ffmpeg录制屏幕+音频，支持MP4、WebM、GIF（GPU编码）" },
