    "Register Ctrl+Q as shortcut to close Discord": { en: "Register Ctrl+Q as shortcut to close Discord", fr: "Enregistrez Ctrl+Q comme raccourci pour fermer Discord", ar: "قم بتسجيل Ctrl+Q كاختصار لإغلاق Discord", es: "Registre Ctrl+Q como acceso directo para cerrar Discord", ru: "Зарегистрируйте Ctrl+Q как ярлык для закрытия Discord", zh: "将 Ctrl+Q 注册为关闭 Discord 的快捷方式" },
    "Rejoins d'abord un salon vocal": { en: "Join a voice channel first", fr: "Rejoins d'abord un salon vocal", ar: "Rejoins d'abord un salon vocal", es: "Únete primero a un canal de voz", ru: "Сначала войдите в голосовой канал", zh: "请先加入语音频道" },
