    "Server ID": { en: "Server ID", fr: "ID du serveur", ar: "معرف الخادم", es: "ID del servidor", ru: "Идентификатор сервера", zh: "服务器ID" },
    "Server IDs to ignore (comma-separated). Messages sent in these servers will NOT be resent.": { en: "Server IDs to ignore (comma-separated). Messages sent in these servers will NOT be resent.", fr: "ID de serveur à ignorer (séparés par des virgules). Les messages envoyés sur ces serveurs ne seront PAS renvoyés.", ar: "معرفات الخادم المطلوب تجاهلها (مفصولة بفواصل). لن تتم إعادة إرسال الرسائل المرسلة في هذه الخوادم.", es: "ID de servidor que se deben ignorar (separados por comas). Los mensajes enviados en estos servidores NO serán reenviados.", ru: "Идентификаторы серверов, которые следует игнорировать (через запятую). Сообщения, отправленные на эти серверы, НЕ будут пересылаться.", zh: "要忽略的服务器 ID（以逗号分隔）。在这些服务器中发送的消息将不会被重新发送。" },
    "Server Notification Settings": { en: "Server Notification Settings", fr: "Paramètres de notification du serveur", ar: "إعدادات إشعارات الخادم", es: "Configuración de notificaciones del servidor", ru: "Настройки уведомлений сервера", zh: "服务器通知设置" },
    "Server Scope": { en: "Server Scope", fr: "Portée du serveur", ar: "نطاق الخادم", es: "Alcance del servidor", ru: "Область действия сервера", zh: "服务器范围" },
    "Server Surveillance": { en: "Server Surveillance", fr: "Surveillance du serveur", ar: "مراقبة الخادم", es: "Vigilancia del servidor", ru: "Наблюдение за сервером", zh: "服务器监控" },
