    "Service configuration.": { en: "Service configuration.", fr: "Configuration des services.", ar: "تكوين الخدمة.", es: "Configuración del servicio.", ru: "Конфигурация сервиса.", zh: "服务配置。" },
    "Sesotho": { en: "Sesotho", fr: "Sésotho", ar: "سيسوتو", es: "sesoto", ru: "сесото", zh: "塞索托语" },
