    "Settings Sync": { en: "Settings Sync", fr: "Synchronisation des paramètres", ar: "مزامنة الإعدادات", es: "Sincronización de configuración", ru: "Синхронизация настроек", zh: "设置同步" },
    "Settings command is unavailable.": { en: "Settings command is unavailable.", fr: "La commande Paramètres n’est pas disponible.", ar: "أمر الإعدادات غير متاح.", es: "El comando de configuración no está disponible.", ru: "Команда настроек недоступна.", zh: "设置命令不可用。" },
    "Settings copied (name, description, etc.)": { en: "Settings copied (name, description, etc.)", fr: "Paramètres copiés (nom, description, etc.)", ar: "تم نسخ الإعدادات (الاسم والوصف وما إلى ذلك)", es: "Configuraciones copiadas (nombre, descripción, etc.)", ru: "Настройки скопированы (имя, описание и т. д.)", zh: "复制的设置（名称、描述等）" },
    "Setup badge layout and visibility": { en: "Setup badge layout and visibility", fr: "Configurer la disposition et la visibilité du badge", ar: "إعداد تخطيط الشارة وإمكانية الرؤية", es: "Configurar el diseño y la visibilidad de la insignia", ru: "Настройка макета и видимости значка", zh: "设置徽章布局和可见性" },
    "Share": { en: "Share", fr: "Share", ar: "Share", es: "Compartir", ru: "Поделиться", zh: "分享" },
