    "Sinhala": { en: "Sinhala", fr: "Cinghalais", ar: "السنهالية", es: "cingalés", ru: "сингальский", zh: "僧伽罗语" },
    "Size of the activity icons": { en: "Size of the activity icons", fr: "Taille des icônes d'activité", ar: "حجم أيقونات النشاط", es: "Tamaño de los iconos de actividad", ru: "Размер значков действий", zh: "活动图标的大小" },
    "Size of the emojis when sending": { en: "Size of the emojis when sending", fr: "Taille des emojis lors de l'envoi", ar: "حجم الرموز التعبيرية عند الإرسال", es: "Tamaño de los emojis al enviar", ru: "Размер смайлов при отправке", zh: "发送时表情符号的大小" },
    "Size of the fatass horse": { en: "Size of the fatass horse", fr: "Taille du cheval fatass", ar: "حجم حصان فاتاس", es: "Tamaño del caballo gordo", ru: "Размер толстой лошади", zh: "胖马的大小" },
    "Size of the stickers when sending": { en: "Size of the stickers when sending", fr: "Taille des autocollants lors de l'envoi", ar: "حجم الملصقات عند الإرسال", es: "Tamaño de las pegatinas al enviar", ru: "Размер стикеров при отправке", zh: "发送时贴纸尺寸" },
    "Skip": { en: "Skip", fr: "Sauter", ar: "يتخطى", es: "Saltar", ru: "Пропускать", zh: "跳过" },
    "Skip deletion confirmation dialogs.": { en: "Skip deletion confirmation dialogs.", fr: "Ignorer les boîtes de dialogue de confirmation de suppression.", ar: "تخطي مربعات حوار تأكيد الحذف.", es: "Omita los cuadros de diálogo de confirmación de eliminación.", ru: "Пропускать диалоговые окна подтверждения удаления.", zh: "跳过删除确认对话框。" },
    "Skip notifications from muted servers, channels, or users": { en: "Skip notifications from muted servers, channels, or users", fr: "Ignorer les notifications des serveurs, canaux ou utilisateurs désactivés", ar: "تخطي الإشعارات الواردة من الخوادم أو القنوات أو المستخدمين الذين تم تجاهلهم", es: "Omitir notificaciones de servidores, canales o usuarios silenciados", ru: "Пропускать уведомления от отключенных серверов, каналов или пользователей.", zh: "跳过来自静音服务器、频道或用户的通知" },
    "Skip users already in your friends": { en: "Skip users already in your friends", fr: "Ignorer les utilisateurs déjà dans vos amis", ar: "تخطي المستخدمين الموجودين بالفعل في أصدقائك", es: "Saltar usuarios que ya están en tus amigos", ru: "Пропускать пользователей, которые уже есть в ваших друзьях", zh: "跳过好友中已有的用户" },
    "Skips the slow and annoying onboarding delay": { en: "Skips the slow and annoying onboarding delay", fr: "Évite le délai d'intégration lent et ennuyeux", ar: "يتخطى التأخير البطيء والمزعج في عملية الصعود", es: "Evita el lento y molesto retraso de incorporación", ru: "Пропускает медленную и раздражающую задержку при регистрации.", zh: "跳过缓慢而烦人的入职延迟" },
    "Skull Medallion": { en: "Skull Medallion", fr: "Médaillon de crâne", ar: "ميدالية الجمجمة", es: "Medallón de calavera", ru: "Череп Медальон", zh: "骷髅奖章" },
    "Slap someone/something.": { en: "Slap someone/something.", fr: "Gifle quelqu'un/quelque chose.", ar: "صفعة شخص/شيء.", es: "Bofetada a alguien/algo.", ru: "Ударить кого-либо/что-либо.", zh: "打某人/某物。" },
    "Slovak": { en: "Slovak", fr: "slovaque", ar: "السلوفاكية", es: "eslovaco", ru: "словацкий", zh: "斯洛伐克语" },
    "Slovenian": { en: "Slovenian", fr: "slovène", ar: "السلوفينية", es: "esloveno", ru: "словенский", zh: "斯洛文尼亚语" },
