    "Voice badge color": { en: "Voice badge color", fr: "Couleur du badge vocal", ar: "لون شارة الصوت", es: "Color de la insignia de voz", ru: "Цвет голосового значка", zh: "语音徽章颜色" },
    "Voice badge label": { en: "Voice badge label", fr: "Étiquette de badge vocal", ar: "تسمية شارة الصوت", es: "Etiqueta de insignia de voz", ru: "Ярлык голосового значка", zh: "语音徽章标签" },
